INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('weak-eyesight-prophetic-medicine-r3','weak-eyesight-prophetic-medicine','clinical','US Food and Drug Administration — Kohl and lead poisoning','Traditional surma/kohl safety','https://www.fda.gov/cosmetics/cosmetic-products/kohl-kajal-al-kahal-surma-tiro-tozali-or-kwalli-any-name-beware-lead-poisoning','Documents lead contamination and poisoning risk.','pending','3');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('weak-eyesight-prophetic-medicine-r4','weak-eyesight-prophetic-medicine','clinical','NHS — Vision loss','Urgent warning signs','https://www.nhs.uk/conditions/vision-loss/','When visual changes or sudden loss need urgent assessment.','pending','4');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('weak-eyesight-prophetic-medicine-r5','weak-eyesight-prophetic-medicine','clinical','National Institute of Diabetes and Digestive and Kidney Diseases','Diabetic eye disease and examination','https://www.niddk.nih.gov/health-information/diabetes/overview/preventing-problems/diabetic-eye-disease','Risk and examination recommendations for people with diabetes.','pending','5');
INSERT OR IGNORE INTO encyclopedia_citations(id,article_id,citation_type,source_title,citation_ref,source_url,source_note,verification_status,sort_order) VALUES('weak-eyesight-prophetic-medicine-r6','weak-eyesight-prophetic-medicine','hadith','Sahih Muslim — Book of Greetings','2204, for every disease a remedy','https://sunnah.com/muslim:2204','General religious teaching; not a prescription for an eye condition.','pending','6');
